<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Check, Pencil, Plus, Trash2, WalletCards } from 'lucide-vue-next'
import { createBudget, createChecklist, deleteBudget, deleteChecklist, getBudget, getChecklist, updateBudget, updateChecklist, type BudgetItem, type BudgetTotal, type ChecklistItem } from '../tripSupportApi'

const props = defineProps<{ itineraryId: string; canEdit: boolean }>()
const checklist = ref<ChecklistItem[]>([])
const budget = ref<BudgetItem[]>([])
const totals = ref<BudgetTotal[]>([])
const loading = ref(true)
const error = ref('')
const checklistDraft = ref({ category: '行前', content: '' })
const budgetDraft = ref({ category: '交通', amount: '', currency: 'CNY', description: '' })
const editingChecklistId = ref('')
const editingBudgetId = ref('')
const busy = ref('')
const checklistGroups = computed(() => checklist.value.reduce<Record<string, ChecklistItem[]>>((groups, item) => { (groups[item.category] ??= []).push(item); return groups }, {}))

function showFailure(message: string) { error.value = message }
async function load() { loading.value = true; error.value = ''; try { const [items, budgetData] = await Promise.all([getChecklist(props.itineraryId), getBudget(props.itineraryId)]); checklist.value = items; budget.value = budgetData.items; totals.value = budgetData.totals } catch { showFailure('清单和预算暂时无法读取，请稍后重试。') } finally { loading.value = false } }
async function refreshTotals() { totals.value = (await getBudget(props.itineraryId)).totals }
async function addChecklist() { if (!props.canEdit || !checklistDraft.value.category.trim() || !checklistDraft.value.content.trim()) return; busy.value = 'checklist-create'; try { checklist.value.push(await createChecklist(props.itineraryId, { category: checklistDraft.value.category.trim(), content: checklistDraft.value.content.trim() })); checklistDraft.value.content = '' } catch { showFailure('清单项没有保存。') } finally { busy.value = '' } }
async function saveChecklist(item: ChecklistItem) { busy.value = item.id; try { const saved = await updateChecklist(props.itineraryId, item.id, { category: item.category.trim(), content: item.content.trim(), checked: item.checked }); checklist.value = checklist.value.map((entry) => entry.id === saved.id ? saved : entry); editingChecklistId.value = '' } catch { showFailure('清单项没有保存。') } finally { busy.value = '' } }
async function toggleChecklist(item: ChecklistItem) { if (!props.canEdit) return; busy.value = item.id; try { const saved = await updateChecklist(props.itineraryId, item.id, { checked: !item.checked }); checklist.value = checklist.value.map((entry) => entry.id === saved.id ? saved : entry) } catch { showFailure('勾选状态没有保存。') } finally { busy.value = '' } }
async function removeChecklist(itemId: string) { busy.value = itemId; try { await deleteChecklist(props.itineraryId, itemId); checklist.value = checklist.value.filter((item) => item.id !== itemId) } catch { showFailure('清单项没有删除。') } finally { busy.value = '' } }
async function addBudget() { if (!props.canEdit || !budgetDraft.value.category.trim() || !budgetDraft.value.amount) return; busy.value = 'budget-create'; try { const item = await createBudget(props.itineraryId, { category: budgetDraft.value.category.trim(), amount: budgetDraft.value.amount, currency: budgetDraft.value.currency.toUpperCase(), description: budgetDraft.value.description.trim() || null }); budget.value.push(item); budgetDraft.value.amount = ''; budgetDraft.value.description = ''; await refreshTotals() } catch { showFailure('预算项没有保存，请检查金额和货币代码。') } finally { busy.value = '' } }
async function saveBudget(item: BudgetItem) { busy.value = item.id; try { const saved = await updateBudget(props.itineraryId, item.id, { category: item.category.trim(), amount: item.amount, description: item.description }); budget.value = budget.value.map((entry) => entry.id === saved.id ? saved : entry); editingBudgetId.value = ''; await refreshTotals() } catch { showFailure('预算项没有保存。') } finally { busy.value = '' } }
async function removeBudget(itemId: string) { busy.value = itemId; try { await deleteBudget(props.itineraryId, itemId); budget.value = budget.value.filter((item) => item.id !== itemId); await refreshTotals() } catch { showFailure('预算项没有删除。') } finally { busy.value = '' } }
onMounted(load)
</script>

<template>
  <section class="support-panel">
<Transition name="fade"><p v-if="error" class="support-error" role="alert">{{ error }}</p></Transition><div v-if="loading" class="support-loading">正在读取执行准备。</div><template v-else><section class="support-section"><header><div><h2>出行清单</h2><span>{{ checklist.filter((item) => item.checked).length }}/{{ checklist.length }} 已完成</span></div></header><form v-if="canEdit" class="quick-form" @submit.prevent="addChecklist"><input v-model="checklistDraft.category" aria-label="清单分类"><input v-model="checklistDraft.content" aria-label="清单内容" placeholder="新增一项准备"><button type="submit" :disabled="busy === 'checklist-create'" title="新增清单" aria-label="新增清单"><Plus :size="16" /></button></form><Transition name="fade"><div v-if="!checklist.length" class="support-empty">从行前准备开始，所有清单都在这里。</div></Transition><div v-for="(items, category) in checklistGroups" :key="category" class="check-group"><h3>{{ category }}</h3><TransitionGroup name="list" tag="div" class="check-items"><article v-for="item in items" :key="item.id" :class="{ checked: item.checked }"><button class="check-toggle" type="button" :disabled="busy === item.id || !canEdit" :title="item.checked ? '标为未完成' : '标为完成'" @click="toggleChecklist(item)"><Check v-if="item.checked" :size="14" /></button><template v-if="editingChecklistId === item.id"><input v-model="item.category" aria-label="清单分类"><input v-model="item.content" aria-label="清单内容"><button type="button" class="text-action" :disabled="busy === item.id" @click="saveChecklist(item)">保存</button></template><template v-else><span>{{ item.content }}</span><button v-if="canEdit" type="button" class="tool-button" title="编辑清单" aria-label="编辑清单" @click="editingChecklistId = item.id"><Pencil :size="14" /></button><button v-if="canEdit" type="button" class="tool-button delete" title="删除清单" aria-label="删除清单" @click="removeChecklist(item.id)"><Trash2 :size="14" /></button></template></article></TransitionGroup></div></section><section class="support-section budget-section"><header><div><h2>预算</h2><span>按币种独立汇总</span></div><WalletCards :size="19" /></header><div class="budget-totals"><strong v-for="total in totals" :key="total.currency">{{ total.currency }} {{ Number(total.total_amount).toFixed(2) }}</strong><span v-if="!totals.length">尚未记录预算</span></div><form v-if="canEdit" class="budget-form" @submit.prevent="addBudget"><input v-model="budgetDraft.category" aria-label="预算分类"><input v-model="budgetDraft.amount" inputmode="decimal" type="number" min="0" step="0.01" aria-label="预算金额" placeholder="金额"><input v-model="budgetDraft.currency" maxlength="3" aria-label="预算货币"><input v-model="budgetDraft.description" aria-label="预算说明" placeholder="说明（可选）"><button type="submit" :disabled="busy === 'budget-create'"><Plus :size="15" />新增</button></form><Transition name="fade"><div v-if="!budget.length" class="support-empty">添加交通、住宿和餐饮等费用，出发前更有底。</div></Transition><TransitionGroup name="list" tag="div" class="budget-items"><article v-for="item in budget" :key="item.id" class="budget-item"><template v-if="editingBudgetId === item.id"><input v-model="item.category" aria-label="预算分类"><input v-model="item.amount" inputmode="decimal" type="number" min="0" step="0.01" aria-label="预算金额"><input v-model="item.description" aria-label="预算说明"><button type="button" class="text-action" :disabled="busy === item.id" @click="saveBudget(item)">保存</button></template><template v-else><div><strong>{{ item.category }}</strong><span>{{ item.description || '未添加说明' }}</span></div><b>{{ item.currency }} {{ Number(item.amount).toFixed(2) }}</b><button v-if="canEdit" type="button" class="tool-button" title="编辑预算" aria-label="编辑预算" @click="editingBudgetId = item.id"><Pencil :size="14" /></button><button v-if="canEdit" type="button" class="tool-button delete" title="删除预算" aria-label="删除预算" @click="removeBudget(item.id)"><Trash2 :size="14" /></button></template></article></TransitionGroup></section></template></section>
</template>

<style scoped>
.support-panel { display: grid; gap: 22px; }.support-section { border-top: 1px solid var(--field-line); padding-top: 16px; }.support-section header { align-items: center; display: flex; justify-content: space-between; }.support-section h2 { font-size: 18px; margin: 0; }.support-section header div { display: grid; gap: 4px; }.support-section header span, .support-empty { color: var(--field-muted); font-size: 12px; }.quick-form, .budget-form { display: grid; gap: 7px; margin: 14px 0; }.quick-form { grid-template-columns: 84px 1fr auto; }.quick-form input, .budget-form input, .check-group article input, .budget-item input { border: 1px solid var(--field-line); min-width: 0; padding: 8px; }.quick-form button, .budget-form button { align-items: center; background: var(--field-deep); border: 0; color: #fff; cursor: pointer; display: inline-flex; justify-content: center; min-height: 36px; padding: 8px 10px; }.budget-form { grid-template-columns: 1fr .8fr 52px 1.4fr auto; }.check-group { margin-top: 16px; }.check-group h3 { color: var(--field-teal); font: 800 11px var(--field-mono); margin: 0 0 6px; }.check-group article, .budget-item { align-items: center; border-top: 1px solid var(--field-line); display: flex; gap: 8px; min-height: 42px; }.check-group article span { flex: 1; font-size: 13px; }.check-group article.checked span { color: var(--field-muted); text-decoration: line-through; }.check-toggle { align-items: center; background: transparent; border: 1px solid var(--field-teal); color: var(--field-teal); cursor: pointer; display: inline-flex; height: 19px; justify-content: center; padding: 0; width: 19px; }.checked .check-toggle { background: var(--field-teal); color: #fff; }.tool-button { background: transparent; border: 0; color: var(--field-muted); cursor: pointer; display: inline-flex; padding: 5px; }.tool-button:hover { color: var(--field-teal); }.tool-button.delete:hover { color: var(--field-coral); }.text-action { background: transparent; border: 0; color: var(--field-teal); cursor: pointer; font-weight: 800; padding: 4px; }.budget-totals { background: var(--field-teal-soft); display: flex; flex-wrap: wrap; gap: 8px 16px; margin: 14px 0; padding: 11px; }.budget-totals strong { color: var(--field-deep); font: 800 13px var(--field-mono); }.budget-totals span { color: var(--field-muted); font-size: 12px; }.budget-item > div { display: grid; flex: 1; gap: 3px; min-width: 0; }.budget-item strong { font-size: 13px; }.budget-item span { color: var(--field-muted); font-size: 11px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.budget-item b { font: 800 12px var(--field-mono); white-space: nowrap; }.support-error { background: #f8ded8; color: #8e3329; font-size: 12px; margin: 0; padding: 10px; }.support-loading, .support-empty { padding: 14px 0; }.budget-item:has(input) { display: grid; grid-template-columns: 1fr .8fr 1.4fr auto; padding: 7px 0; } @media (max-width: 560px) { .budget-form { grid-template-columns: 1fr 1fr 52px; }.budget-form input:nth-of-type(4) { grid-column: span 2; }.budget-form button { grid-column: 3; grid-row: 2; }.budget-item:has(input) { grid-template-columns: 1fr 1fr; }.budget-item:has(input) input:last-of-type { grid-column: span 2; } }
/* Practical trip support follows the same calm journal treatment as the route. */
.support-panel{--travel-ink:var(--field-ink);--travel-muted:var(--field-muted);--travel-line:var(--field-line);--travel-sea:var(--field-teal);--travel-coral:var(--field-coral);gap:28px;animation:reveal-soft var(--motion-slow) var(--ease-out) both}.support-section{border-top-color:var(--travel-line);padding-top:20px}.support-section h2{font-family:Georgia,"Noto Serif SC",serif;font-size:21px;font-weight:600}.support-section header span,.support-empty{color:var(--travel-muted)}.quick-form input,.budget-form input,.check-group article input,.budget-item input{background:#fcfffd;border-color:#c9ddd5;border-radius:7px;transition:border-color var(--motion-fast) var(--ease-standard),box-shadow var(--motion-fast) var(--ease-standard)}.quick-form input:focus,.budget-form input:focus,.check-group article input:focus,.budget-item input:focus{border-color:var(--travel-sea);box-shadow:var(--shadow-focus);outline:0}.quick-form button,.budget-form button{background:var(--travel-sea);border-radius:7px;transition:background-color var(--motion-base) var(--ease-standard),transform var(--motion-fast) var(--ease-standard),opacity var(--motion-fast) var(--ease-standard)}.quick-form button:active:not(:disabled),.budget-form button:active:not(:disabled){transform:scale(.97)}.check-group h3{color:var(--travel-coral)}.check-group article,.budget-item{border-top-color:var(--travel-line)}.check-toggle{border-color:var(--travel-sea);border-radius:50%;color:var(--travel-sea);transition:background-color var(--motion-fast) var(--ease-standard),color var(--motion-fast) var(--ease-standard)}.checked .check-toggle{background:var(--travel-sea)}.tool-button:hover,.text-action{color:var(--travel-sea)}.budget-totals strong{background:#edf7f2;border-radius:999px;color:var(--travel-sea);padding:6px 9px}.support-error{background:#fff0eb;border-left:3px solid var(--travel-coral);color:#9c4234;padding:10px}.quick-form button:hover:not(:disabled),.budget-form button:hover:not(:disabled){opacity:.9}.check-toggle:hover:not(:disabled){opacity:.85}.check-items,.budget-items{display:grid}@media (prefers-reduced-motion: reduce){.support-panel{animation:none}.quick-form input,.quick-form button,.check-toggle{transition:none}}
</style>
